package com.wandertrace.controller;import com.wandertrace.dto.*;import com.wandertrace.dto.ContentDtos.*;import com.wandertrace.security.CurrentUser;import com.wandertrace.service.MemoryService;import jakarta.servlet.http.HttpSession;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController public class MemoryController {private final MemoryService service;private final CurrentUser current;public MemoryController(MemoryService s,CurrentUser c){service=s;current=c;}private UUID user(HttpSession s){return current.require(s);}@GetMapping("/api/destinations/{id}/memories")ApiResponse<List<Memory>>list(@PathVariable UUID id,HttpSession s){return ApiResponse.ok(service.list(user(s),id));}@PostMapping("/api/destinations/{id}/memories")@ResponseStatus(HttpStatus.CREATED)ApiResponse<Memory>create(@PathVariable UUID id,@Valid @RequestBody MemoryRequest r,HttpSession s){return ApiResponse.ok(service.create(user(s),id,r));}@GetMapping("/api/memories/{id}")ApiResponse<Memory>get(@PathVariable UUID id,HttpSession s){return ApiResponse.ok(service.get(user(s),id));}@PutMapping("/api/memories/{id}")ApiResponse<Memory>update(@PathVariable UUID id,@Valid @RequestBody MemoryRequest r,HttpSession s){return ApiResponse.ok(service.update(user(s),id,r));}@DeleteMapping("/api/memories/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void delete(@PathVariable UUID id,HttpSession s){service.delete(user(s),id);}}
